// public-submit-evaluation
//
// The Edge Function a client's Close-Out Evaluation link (the per-client
// evaluation.html generated by client_profile.html's "Generate Link"
// button, published to the public client-evaluations storage bucket)
// submits to. There's no Supabase session behind this page at all -- a CEO
// just opens the link, fills it out, hits Submit -- so this function is
// the entire write path, same "no session to attach the write to" model as
// public-submit-application (066): validate what came in, then write with
// the service-role client (never the anon key).
//
// Greg (8/25/26): "getting a busy CEO to fill it out, AND email it back to
// us is a 50/50 chance... if we can just have a link that the CEO fills
// out and that link is added to the Close Out button I don't think we need
// email." This function is that direct write -- no PDF, no email, no
// manual upload step. The moment this succeeds, get_client_public_view()/
// finalize_client() (078) already see a non-null evaluation_submitted_at,
// so the client dashboard's Close-Out step and CTA banner update
// immediately, and an in-app bell notification (078's trigger) tells the
// team a response is waiting to be reviewed in client_profile.html.
//
// Auth model: the page sends the project's anon key as the
// Authorization/apikey headers (same as every other page in this app) --
// enough to satisfy Supabase's platform-level "is this a validly signed
// request" check. This function does NOT require Super Admin or any
// signed-in user -- anyone with the link can submit, same as the public
// application form.
//
// HOW TO DEPLOY (no CLI, no Terminal)
//   1. Supabase Dashboard -> Edge Functions -> New Function -> name it
//      "public-submit-evaluation"
//   2. Paste this whole file in, Deploy
//   That's it -- no secrets needed (no Resend here on purpose; see the
//   078 migration header for why). SUPABASE_URL and
//   SUPABASE_SERVICE_ROLE_KEY are already available to every Edge Function
//   automatically.

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function jsonResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

// Bounds on the free-text fields -- this endpoint has no authenticated
// caller to trust, so nothing from the request body is written through
// unbounded.
const MAX_TEXT = 5000;
function clampText(v: unknown): string | null {
  if (v === undefined || v === null) return null;
  const s = String(v).trim();
  if (!s) return null;
  return s.slice(0, MAX_TEXT);
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }
  if (req.method !== "POST") {
    return jsonResponse({ error: "Method not allowed." }, 405);
  }

  try {
    const body = await req.json().catch(() => ({}));
    const clientId = (body.clientId || "").trim();
    const data = body.data || {};

    if (!clientId) {
      return jsonResponse({ error: "Missing client." }, 400);
    }

    const questionRatings = Array.isArray(data.questionRatings) ? data.questionRatings : [];
    if (!questionRatings.length) {
      return jsonResponse({ error: "Please answer at least one research question before submitting." }, 400);
    }
    const cleanRatings = questionRatings
      .map((r: any) => ({
        question: clampText(r && r.question) || "",
        rating: ["very", "partial", "not"].includes(r && r.rating) ? r.rating : null,
      }))
      .filter((r: any) => r.question || r.rating);

    const referrals = Array.isArray(data.referrals) ? data.referrals : [];
    const cleanReferrals = referrals
      .map((r: any) => ({
        name: clampText(r && r.name),
        company: clampText(r && r.company),
        contact: clampText(r && r.contact),
      }))
      .filter((r: any) => r.name || r.company || r.contact);

    const npsScoreRaw = data.npsScore;
    const npsScore = Number.isFinite(Number(npsScoreRaw)) && npsScoreRaw !== null && npsScoreRaw !== ""
      ? Math.max(1, Math.min(10, Math.round(Number(npsScoreRaw))))
      : null;

    const countInt = (v: unknown) => {
      const n = Number(v);
      return Number.isFinite(n) && n >= 0 ? Math.round(n) : 0;
    };

    const adminClient = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
      { auth: { autoRefreshToken: false, persistSession: false } },
    );

    const { data: client, error: clientErr } = await adminClient
      .from("clients")
      .select("id")
      .eq("id", clientId)
      .maybeSingle();
    if (clientErr) return jsonResponse({ error: clientErr.message }, 400);
    if (!client) return jsonResponse({ error: "Unknown client link. Please double-check the URL you were given." }, 400);

    const { error: insertErr } = await adminClient.from("client_evaluation_responses").insert({
      client_id: clientId,
      respondent_name: clampText(data.respondentName),
      respondent_date: clampText(data.respondentDate),
      company_name: clampText(data.companyName),
      sponsor_name: clampText(data.sponsorName),
      question_ratings: cleanRatings,
      q1_explain: clampText(data.q1Explain),
      prepared: ["yes", "no"].includes(data.prepared) ? data.prepared : null,
      prepared_explain: clampText(data.preparedExplain),
      improvement_suggestions: clampText(data.improvementSuggestions),
      nps_score: npsScore,
      nps_explain: clampText(data.npsExplain),
      referrals: cleanReferrals,
      testimonial: clampText(data.testimonial),
      very_useful_count: countInt(data.veryUsefulCount),
      partially_useful_count: countInt(data.partiallyUsefulCount),
      not_useful_count: countInt(data.notUsefulCount),
      weighted_score: countInt(data.weightedScore),
      weighted_max: countInt(data.weightedMax),
    });

    if (insertErr) return jsonResponse({ error: insertErr.message }, 400);

    return jsonResponse({ ok: true });
  } catch (e) {
    return jsonResponse({ error: e instanceof Error ? e.message : "Unexpected error." }, 500);
  }
});
